/bin/bash -lc "python - <<'PY'
import requests
for pkg in ['r-readxl','r-tidyverse','r-base','scipy','statsmodels','r-xlconnect']:
 url=f'https://api.anaconda.org/package/bioconda/{pkg}'
 try:
  r=requests.get(url, timeout=20)
  print(pkg, r.status_code)
  if r.ok:
   data=r.json(); files=data.get('files',[])
   for f in files[-5:]:
    attrs=f.get('attrs',{})
    print(' ', f.get('version'), f.get('basename'), attrs.get('build'))
 except Exception as e: print(pkg, type(e).__name__, e)
PY"

/bin/bash -lc "python - <<'PY'
import requests
for channel in ['conda-forge','bioconda']:
 for pkg in ['r-readxl','r-statmod','r-base','scipy','statsmodels','xlrd','r-openxlsx']:
  url=f'https://api.anaconda.org/package/{channel}/{pkg}'
  try:
   r=requests.get(url, timeout=20)
   if r.ok:
    print(channel, pkg, 'ok')
    files=r.json().get('files',[])
    for f in files[-3:]: print(' ', f.get('version'), f.get('basename'), f.get('attrs',{}).get('build'))
  except Exception as e: pass
PY"

